from __future__ import annotations

import torch

from .fused_ffn import NAMES, _check, _library


def make_wrappers(scratch, selected_names=None) -> dict:
    """Pack immutable gate/up weights during warmup and bind scratch buffers.

    Shapes, bf16 roundings, mutations and capture requirements match fused_ffn.
    Each closure retains both source tensors and the packed buffer for every
    distinct weight pair. Packing uses scratch, so warmup must visit all pairs
    before it freezes; 18 layers add 288 MiB of packed weights.
    """
    names = set(NAMES) if selected_names is None else set(selected_names)
    unknown = names - set(NAMES)
    if unknown:
        raise KeyError(f"packed FFN backend does not implement {sorted(unknown)}")
    weights = {}
    workspaces = {}
    role = f"pi05_packed_ffn_{id(weights)}"

    def action_expert_norm_gated_ffn(x, scale, gate_w, up_w, gate_b, up_b,
                                     out, norm_factor):
        pair = (gate_w.data_ptr(), up_w.data_ptr())
        if pair not in weights:
            packed = scratch(role + f"_weight_{len(weights)}", (1024, 8192),
                             gate_w.dtype, gate_w.device)
            packed[:, :4096].copy_(gate_w)
            packed[:, 4096:].copy_(up_w)
            weights[pair] = (gate_w, up_w, packed)
        packed = weights[pair][2]
        rows = x.shape[0]
        key = (rows, x.dtype, x.device)
        if key not in workspaces:
            workspaces[key] = (
                scratch(role + "_a", (rows, 1024), x.dtype, x.device),
                scratch(role + "_both", (rows, 8192), x.dtype, x.device),
            )
        a, both = workspaces[key]
        lib = _library()
        stream = torch.cuda.current_stream().cuda_stream
        _check(lib.ada_rms_launch(x.data_ptr(), scale.data_ptr(), a.data_ptr(),
                                 norm_factor.data_ptr(), rows, stream), "ada_rms", rows)
        torch.mm(a, packed, out=both)
        _check(lib.packed_gated_activation_launch(
            both.data_ptr(), both.data_ptr() + 4096 * both.element_size(),
            gate_b.data_ptr(), up_b.data_ptr(), out.data_ptr(), rows, stream),
            "packed_gated_activation", rows)
        return out

    return {name: action_expert_norm_gated_ffn for name in names}


__all__ = ["NAMES", "make_wrappers"]
"""Pi0.5 RTX 5090 expert projections with a fused gated residual update."""
from __future__ import annotations

import torch

from .fused_ffn import _check, _library

NAMES = ("action_expert_out_proj_residual", "action_expert_ffn_down_residual")


def make_wrappers(scratch, selected_names=None) -> dict:
    """Bind bf16 CUDA MxK @ Kx1024, then out += projection * gate in fp32.

    K is 2048 for the attention projection and 4096 for FFN down; gate is
    (1024,) and out is contiguous (M, 1024), read and written in place. The
    bf16 GEMM output lives in scratch. Warmup builds CUDA and allocates this
    buffer before scratch freezes and the runner captures its graph.
    """
    names = set(NAMES) if selected_names is None else set(selected_names)
    unknown = names - set(NAMES)
    if unknown:
        raise KeyError(f"fused residual backend does not implement {sorted(unknown)}")
    workspaces = {}
    role = f"pi05_fused_residual_{id(workspaces)}"

    def projection_residual(x, weight, gate, out):
        rows = x.shape[0]
        key = (rows, x.dtype, x.device)
        if key not in workspaces:
            workspaces[key] = scratch(role, (rows, 1024), x.dtype, x.device)
        projected = workspaces[key]
        torch.mm(x, weight, out=projected)
        _check(_library().gated_residual_launch(
            projected.data_ptr(), gate.data_ptr(), out.data_ptr(), rows,
            torch.cuda.current_stream().cuda_stream), "gated_residual", rows)
        return out

    return {name: projection_residual for name in names}


__all__ = ["NAMES", "make_wrappers"]
}

__global__ void ada_rms_kernel(const bf16 *__restrict__ x,
                               const bf16 *__restrict__ scale,
                               bf16 *__restrict__ a,
                               bf16 *__restrict__ factor) {
  const int32_t row = blockIdx.x;
  const int32_t lane = threadIdx.x & 31;
  const int32_t warp = threadIdx.x >> 5;
  float values[4];
  float sum = 0.f;
#pragma unroll
  for (int32_t i = 0; i < 4; ++i) {
    values[i] = __bfloat162float(x[row * 1024 + threadIdx.x + i * 256]);
    sum += values[i] * values[i];
  }
  sum = warp_sum(sum);
  __shared__ float partial[8];
  __shared__ float rounded_factor;
  if (lane == 0) partial[warp] = sum;
  // All eight warp sums must be visible before the first warp reduces them.
  __syncthreads();
  if (warp == 0) {
    sum = warp_sum(lane < 8 ? partial[lane] : 0.f);
    if (lane == 0) {
      const bf16 f = __float2bfloat16_rn(rsqrtf(sum / 1024.f + 1e-6f));
      factor[row] = f;
      rounded_factor = __bfloat162float(f);
    }
  }
  // Broadcast the rounded factor before consuming it in each activation.
  __syncthreads();
#pragma unroll
  for (int32_t i = 0; i < 4; ++i) {
    const int32_t col = threadIdx.x + i * 256;
    const bf16 normalized = __float2bfloat16_rn(values[i] * rounded_factor);
    a[row * 1024 + col] = __float2bfloat16_rn(
        __bfloat162float(normalized) * __bfloat162float(scale[col]));
  }
}

